=== case_id ===
Case-14-commute-261

=== 用户原始指令 (query.txt) ===
整个能点导航去某地的卡片嘛，顺便把天气也显示出来

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个能点导航去某地的卡片嘛，顺便把天气也显示出来",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "StartNavigate",
        "params": {
          "dstLocation": {
            "latitude": {
              "path": "/commute/destination/latitude"
            },
            "longitude": {
              "path": "/commute/destination/longitude"
            }
          },
          "trafficpe": {
            "path": "/commute/trafficType"
          }
        }
      }
    }
  ],
  "dataModel": {
    "value": {
      "commute": {
        "title": "通勤导航",
        "actionText": "导航",
        "trafficType": "Drive",
        "destination": {
          "name": "某地",
          "latitude": "",
          "longitude": ""
        }
      },
      "data": {
        "weather": {
          "location": {},
          "current": {
            "temperatureText": "--°",
            "condition": "天气"
          },
          "daily": [],
          "updatedAt": ""
        }
      },
      "state": {
        "loading": true
      }
    }
  },
  "assetCandidates": []
}

